'use client';

import { useEffect, useId, useRef, useState } from 'react';
import type { CSSProperties, ReactNode } from 'react';
import './morphing-popover.css';

export interface MorphingPopoverProps {
  /** Decorative content for the native pill button. Do not nest other controls. */
  trigger: ReactNode;
  /** Accessible name for the expanded card. */
  label: string;
  children: ReactNode;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  collapsedWidth?: number;
  expandedWidth?: number;
  /** Shape transition in milliseconds, clamped to 160–900. */
  duration?: number;
  className?: string;
}

const finite = (value: number, fallback: number, min: number, max: number) =>
  Number.isFinite(value) ? Math.min(max, Math.max(min, value)) : fallback;

/** One surface morphs between a compact pill and an accessible, nonmodal card. */
export function MorphingPopover({
  trigger, label, children, open, defaultOpen = false, onOpenChange,
  collapsedWidth = 240, expandedWidth = 350, duration = 420, className = '',
}: MorphingPopoverProps) {
  const [internalOpen, setInternalOpen] = useState(defaultOpen);
  const expanded = open ?? internalOpen;
  const rootRef = useRef<HTMLDivElement>(null);
  const panelRef = useRef<HTMLDivElement>(null);
  const triggerRef = useRef<HTMLButtonElement>(null);
  const closeRef = useRef<HTMLButtonElement>(null);
  const previousOpen = useRef(expanded);
  const restoreFocus = useRef(false);
  const moveFocus = useRef(false);
  const focusInside = useRef(false);
  const outsideClose = useRef(false);
  const panelId = `ac-morph-panel-${useId()}`;
  const width = finite(expandedWidth, 350, 240, 560);
  const style = {
    '--ac-morph-collapsed-width': `${Math.min(width, finite(collapsedWidth, 240, 160, 360))}px`,
    '--ac-morph-expanded-width': `${width}px`,
    '--ac-morph-duration': `${finite(duration, 420, 160, 900)}ms`,
  } as CSSProperties;

  function requestOpen(next: boolean, focus = true) {
    if (next === expanded) return;
    outsideClose.current = !focus;
    if (next) moveFocus.current = focus;
    else restoreFocus.current = focus && Boolean(rootRef.current?.contains(document.activeElement));
    if (open === undefined) setInternalOpen(next);
    onOpenChange?.(next);
  }

  useEffect(() => {
    const root = rootRef.current;
    const panel = panelRef.current;
    if (!root || !panel) return;
    let active = true;
    function measure() {
      if (!active || !root || !panel) return;
      // The hidden panel keeps its natural layout; no scaled text or duplicate tree.
      root.style.setProperty('--ac-morph-open-height', `${Math.ceil(panel.getBoundingClientRect().height)}px`);
    }
    measure();
    root.dataset.ready = 'true';
    const observer = typeof ResizeObserver === 'undefined' ? null : new ResizeObserver(measure);
    observer?.observe(panel);
    window.addEventListener('resize', measure);
    return () => {
      active = false;
      observer?.disconnect();
      window.removeEventListener('resize', measure);
    };
  }, []);

  useEffect(() => {
    const changed = previousOpen.current !== expanded;
    previousOpen.current = expanded;
    if (!changed) return;
    if (expanded) {
      if (moveFocus.current || rootRef.current?.contains(document.activeElement)) {
        closeRef.current?.focus({ preventScroll: true });
      }
      moveFocus.current = false;
    } else {
      // Controlled closure from a child action also returns focus to the pill.
      const focusStillHere = document.activeElement === document.body || Boolean(rootRef.current?.contains(document.activeElement));
      if (!outsideClose.current && !document.hidden && focusStillHere && (restoreFocus.current || focusInside.current)) {
        triggerRef.current?.focus({ preventScroll: true });
      }
      restoreFocus.current = false;
    }
    outsideClose.current = false;
  }, [expanded]);

  useEffect(() => {
    if (!expanded) return;
    const dismiss = (event: PointerEvent) => {
      if (event.target instanceof Node && !rootRef.current?.contains(event.target)) requestOpen(false, false);
    };
    document.addEventListener('pointerdown', dismiss);
    return () => document.removeEventListener('pointerdown', dismiss);
  }, [expanded, open, onOpenChange]);

  return <div
    ref={rootRef}
    className={`ac-morph-popover ${className}`.trim()}
    style={style}
    data-open={expanded}
    onFocusCapture={() => { focusInside.current = true; outsideClose.current = false; }}
    onBlurCapture={event => {
      if (event.relatedTarget instanceof Node && !rootRef.current?.contains(event.relatedTarget)) {
        focusInside.current = false;
        restoreFocus.current = false;
        moveFocus.current = false;
      }
    }}
    onKeyDown={event => {
      if (event.key === 'Escape' && expanded && !event.defaultPrevented) {
        event.preventDefault();
        event.stopPropagation();
        requestOpen(false);
      }
    }}
  >
    <div className="ac-morph-popover__surface" aria-hidden="true"><div className="ac-morph-popover__grain"/></div>
    <div className="ac-morph-popover__motes" aria-hidden="true"><i/><i/><i/><i/><i/><i/></div>
    <button
      ref={element => { triggerRef.current = element; if (element) element.inert = expanded; }}
      type="button"
      className="ac-morph-popover__trigger"
      aria-label={`Open ${label}`}
      aria-expanded={expanded}
      aria-controls={panelId}
      aria-haspopup="dialog"
      aria-hidden={expanded}
      tabIndex={expanded ? -1 : 0}
      onClick={() => requestOpen(true)}
    >{trigger}</button>
    <div
      ref={element => { panelRef.current = element; if (element) element.inert = !expanded; }}
      id={panelId}
      role="dialog"
      aria-label={label}
      aria-hidden={!expanded}
      className="ac-morph-popover__panel"
    >
      <button ref={closeRef} type="button" className="ac-morph-popover__close" aria-label={`Close ${label}`} onClick={() => requestOpen(false)}>
        <svg width="13" height="13" viewBox="0 0 16 16" fill="none" aria-hidden="true"><path d="m4 4 8 8M12 4l-8 8"/></svg>
      </button>
      <div className="ac-morph-popover__body">{children}</div>
    </div>
  </div>;
}

.ac-morph-popover { --ac-morph-surface: #252625; --ac-morph-text: #f4f4ef; --ac-morph-muted: #a2a4a0; --ac-morph-border: #ffffff15; --ac-morph-open-height: 260px; --ac-morph-ease: cubic-bezier(.22, 1.12, .36, 1); position: relative; isolation: isolate; width: min(100%, var(--ac-morph-expanded-width, 350px)); height: 52px; color: var(--ac-morph-text); font-family: Arial, Helvetica, sans-serif; text-align: left; }
.ac-morph-popover, .ac-morph-popover * { box-sizing: border-box; }
.ac-morph-popover[data-ready="true"] { transition: height var(--ac-morph-duration, 420ms) var(--ac-morph-ease); }
.ac-morph-popover[data-open="true"] { height: var(--ac-morph-open-height); }
.ac-morph-popover__surface { position: absolute; top: 50%; left: 50%; width: min(100%, var(--ac-morph-collapsed-width, 240px)); height: 52px; transform: translate(-50%, -50%); overflow: hidden; border: 1px solid var(--ac-morph-border); border-radius: 26px; background: var(--ac-morph-surface); box-shadow: 0 7px 16px #0002, inset 0 1px #ffffff05; pointer-events: none; }
.ac-morph-popover[data-ready="true"] .ac-morph-popover__surface { transition: width var(--ac-morph-duration, 420ms) var(--ac-morph-ease), height var(--ac-morph-duration, 420ms) var(--ac-morph-ease), border-radius var(--ac-morph-duration, 420ms) var(--ac-morph-ease), box-shadow var(--ac-morph-duration, 420ms) ease; }
.ac-morph-popover[data-open="true"] .ac-morph-popover__surface { width: 100%; height: var(--ac-morph-open-height); border-radius: 22px; box-shadow: 0 16px 44px #0004, inset 0 1px #ffffff08; }
.ac-morph-popover__grain { position: absolute; inset: 0; opacity: .04; background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 160 160' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.84' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Cpath fill='%23fff' filter='url(%23n)' d='M0 0h160v160H0z'/%3E%3C/svg%3E"); background-size: 160px 160px; }
.ac-morph-popover__trigger { position: absolute; z-index: 2; top: 50%; left: 50%; display: flex; align-items: center; justify-content: center; gap: 10px; width: min(100%, var(--ac-morph-collapsed-width, 240px)); min-width: 0; height: 52px; padding: 0 16px; transform: translate(-50%, -50%); border: 0; border-radius: 26px; background: transparent; color: inherit; font-family: inherit; font-size: 12px; font-weight: 400; line-height: 1.4; cursor: pointer; opacity: 1; visibility: visible; filter: blur(0); transition: opacity calc(var(--ac-morph-duration, 420ms) * .25) ease calc(var(--ac-morph-duration, 420ms) * .6), filter calc(var(--ac-morph-duration, 420ms) * .3) ease calc(var(--ac-morph-duration, 420ms) * .55), visibility 0s; }
.ac-morph-popover[data-open="true"] .ac-morph-popover__trigger { opacity: 0; filter: blur(5px); visibility: hidden; pointer-events: none; transition: opacity calc(var(--ac-morph-duration, 420ms) * .16) ease, filter calc(var(--ac-morph-duration, 420ms) * .2) ease, visibility 0s calc(var(--ac-morph-duration, 420ms) * .2); }
.ac-morph-popover__trigger:hover { background: #ffffff04; }
.ac-morph-popover__trigger:focus-visible { outline: 2px solid var(--ac-morph-text); outline-offset: 4px; }
.ac-morph-popover__panel { position: absolute; z-index: 3; top: 50%; left: 0; width: 100%; max-height: min(520px, calc(100dvh - 96px)); overflow: auto; overscroll-behavior: contain; transform: translateY(calc(-50% + 6px)); border-radius: 22px; opacity: 0; filter: blur(8px); visibility: hidden; pointer-events: none; transition: opacity calc(var(--ac-morph-duration, 420ms) * .17) ease, filter calc(var(--ac-morph-duration, 420ms) * .2) ease, transform calc(var(--ac-morph-duration, 420ms) * .3) ease, visibility 0s calc(var(--ac-morph-duration, 420ms) * .2); scrollbar-width: thin; }
.ac-morph-popover[data-open="true"] .ac-morph-popover__panel { transform: translateY(-50%); opacity: 1; filter: blur(0); visibility: visible; pointer-events: auto; transition: opacity calc(var(--ac-morph-duration, 420ms) * .4) ease calc(var(--ac-morph-duration, 420ms) * .4), filter calc(var(--ac-morph-duration, 420ms) * .5) ease calc(var(--ac-morph-duration, 420ms) * .3), transform calc(var(--ac-morph-duration, 420ms) * .6) var(--ac-morph-ease) calc(var(--ac-morph-duration, 420ms) * .25), visibility 0s; }
.ac-morph-popover[data-open="true"]:not([data-ready="true"]) { height: auto; }
.ac-morph-popover[data-open="true"]:not([data-ready="true"]) .ac-morph-popover__panel { position: relative; top: auto; transform: none; }
.ac-morph-popover[data-open="true"]:not([data-ready="true"]) .ac-morph-popover__surface { height: 100%; }
.ac-morph-popover__body { padding: 24px 22px 20px; }
.ac-morph-popover__close { position: absolute; top: 9px; right: 9px; display: grid; place-items: center; width: 36px; height: 36px; padding: 0; border: 0; border-radius: 50%; background: transparent; color: var(--ac-morph-muted); cursor: pointer; }
.ac-morph-popover__close svg { stroke: currentColor; stroke-width: 1.3; stroke-linecap: round; }
.ac-morph-popover__close:hover { background: #ffffff08; color: var(--ac-morph-text); }
.ac-morph-popover__close:focus-visible { outline: 2px solid var(--ac-morph-text); outline-offset: -3px; }
.ac-morph-popover__motes { position: absolute; z-index: -1; inset: -14px -10px; opacity: 0; pointer-events: none; }
.ac-morph-popover__motes i { position: absolute; width: 1.5px; height: 1.5px; border-radius: 50%; background: var(--ac-morph-text); opacity: .35; }
.ac-morph-popover__motes i:nth-child(1) { top: 12%; left: 8%; } .ac-morph-popover__motes i:nth-child(2) { top: 53%; left: 0; } .ac-morph-popover__motes i:nth-child(3) { top: 89%; left: 18%; } .ac-morph-popover__motes i:nth-child(4) { top: 0; right: 19%; } .ac-morph-popover__motes i:nth-child(5) { top: 31%; right: 0; } .ac-morph-popover__motes i:nth-child(6) { bottom: 0; right: 8%; }
.ac-morph-popover[data-open="true"] .ac-morph-popover__motes { animation: ac-morph-motes var(--ac-morph-duration, 420ms) ease both; }
@keyframes ac-morph-motes { 0%, 100% { opacity: 0; transform: scale(.96); } 45% { opacity: .7; } 90% { transform: scale(1.03); } }
@media (pointer: coarse) { .ac-morph-popover__close { top: 5px; right: 5px; width: 44px; height: 44px; } }
@media (prefers-reduced-motion: reduce) { .ac-morph-popover, .ac-morph-popover__surface, .ac-morph-popover__panel, .ac-morph-popover__trigger { transition: none !important; filter: none !important; } .ac-morph-popover__motes { animation: none !important; } }
